from pathlib import Path

path = Path('src/js/07-reading-voice-bootstrap.part.js')
s = path.read_text(encoding='utf-8')

old = """    let handled=false,audioStarted=false,startFallback=null;\n    const recognitionIsCurrent=()=>token===voiceListenToken&&appState.voiceRecognition===rec&&contextKey===appState.voiceContextKey;\n    const markAudioCaptureStarted=()=>{if(!recognitionIsCurrent())return;audioStarted=true;if(startFallback){clearTimeout(startFallback);startFallback=null;}voiceMicStarting=false;appState.voiceListening=true;syncVoiceUi();};\n    rec.onstart=()=>{if(!recognitionIsCurrent())return;startFallback=setTimeout(()=>{if(recognitionIsCurrent()&&!audioStarted)markAudioCaptureStarted();},300);};\n    rec.onaudiostart=markAudioCaptureStarted;\n    rec.onresult=e=>{if(!recognitionIsCurrent())return;handled=true;voiceMicStarting=false;appState.voiceListening=false;syncVoiceUi();const result=e.results?.[e.resultIndex??0]||e.results?.[0],alternatives=result?[...result]:[],transcripts=alternatives.map(a=>String(a?.transcript||'').trim()).filter(Boolean);let transcript=transcripts[0]||'';if(!answerSurface&&transcripts.length>1&&actions.length){let bestScore=-1;for(const candidate of transcripts){const score=rankedVoiceActions(candidate,actions)[0]?.score||0;if(score>bestScore){bestScore=score;transcript=candidate;}}}if(answerSurface)handleVoiceAnswerTranscript(transcript,answerSurface);else handleVoiceTranscript(transcript,actions);};\n    rec.onnomatch=()=>{if(!recognitionIsCurrent())return;handled=true;voiceMicStarting=false;appState.voiceListening=false;syncVoiceUi();handleVoiceTranscript('',actions);};\n    rec.onerror=e=>{if(!recognitionIsCurrent()&&String(e?.error||'')!=='aborted')return;handled=true;if(startFallback){clearTimeout(startFallback);startFallback=null;}voiceMicStarting=false;appState.voiceListening=false;syncVoiceUi();const code=String(e?.error||'');if(/not-allowed|service-not-allowed/.test(code)){readingMicPermissionDenied=true;toast('Permita o uso do microfone para responder por voz.');return;}if(!/aborted/.test(code))setTimeout(()=>{if(appState.readingAssistEnabled&&token===voiceListenToken)startVoiceListening(actions,contextKey,answerSurface);},300);};\n    rec.onend=()=>{if(startFallback){clearTimeout(startFallback);startFallback=null;}if(appState.voiceRecognition===rec)appState.voiceRecognition=null;const wasListening=!!appState.voiceListening;voiceMicStarting=false;appState.voiceListening=false;syncVoiceUi();if(!handled&&wasListening&&appState.readingAssistEnabled&&token===voiceListenToken)setTimeout(()=>startVoiceListening(actions,contextKey,answerSurface),260);};\n"""

new = """    let handled=false,audioStarted=false,captureReady=false,earlySpeech=false,retryAfterEarlySpeech=false,startFallback=null,readyTimer=null;\n    const recognitionIsCurrent=()=>token===voiceListenToken&&appState.voiceRecognition===rec&&contextKey===appState.voiceContextKey;\n    const clearVoiceStartTimers=()=>{if(startFallback){clearTimeout(startFallback);startFallback=null;}if(readyTimer){clearTimeout(readyTimer);readyTimer=null;}};\n    const markAudioCaptureStarted=()=>{if(!recognitionIsCurrent()||audioStarted)return;audioStarted=true;if(startFallback){clearTimeout(startFallback);startFallback=null;}voiceMicStarting=true;appState.voiceListening=false;syncVoiceUi();readyTimer=setTimeout(()=>{readyTimer=null;if(!recognitionIsCurrent())return;captureReady=true;voiceMicStarting=false;appState.voiceListening=true;syncVoiceUi();},400);};\n    rec.onstart=()=>{if(!recognitionIsCurrent())return;startFallback=setTimeout(()=>{if(recognitionIsCurrent()&&!audioStarted)markAudioCaptureStarted();},300);};\n    rec.onaudiostart=markAudioCaptureStarted;\n    rec.onspeechstart=()=>{if(recognitionIsCurrent()&&!captureReady)earlySpeech=true;};\n    rec.onresult=e=>{if(!recognitionIsCurrent())return;if(!captureReady||earlySpeech){handled=true;retryAfterEarlySpeech=true;voiceMicStarting=false;appState.voiceListening=false;syncVoiceUi();return;}handled=true;clearVoiceStartTimers();voiceMicStarting=false;appState.voiceListening=false;syncVoiceUi();const result=e.results?.[e.resultIndex??0]||e.results?.[0],alternatives=result?[...result]:[],transcripts=alternatives.map(a=>String(a?.transcript||'').trim()).filter(Boolean);let transcript=transcripts[0]||'';if(!answerSurface&&transcripts.length>1&&actions.length){let bestScore=-1;for(const candidate of transcripts){const score=rankedVoiceActions(candidate,actions)[0]?.score||0;if(score>bestScore){bestScore=score;transcript=candidate;}}}if(answerSurface)handleVoiceAnswerTranscript(transcript,answerSurface);else handleVoiceTranscript(transcript,actions);};\n    rec.onnomatch=()=>{if(!recognitionIsCurrent())return;if(!captureReady||earlySpeech){handled=true;retryAfterEarlySpeech=true;voiceMicStarting=false;appState.voiceListening=false;syncVoiceUi();return;}handled=true;clearVoiceStartTimers();voiceMicStarting=false;appState.voiceListening=false;syncVoiceUi();handleVoiceTranscript('',actions);};\n    rec.onerror=e=>{if(!recognitionIsCurrent()&&String(e?.error||'')!=='aborted')return;handled=true;clearVoiceStartTimers();voiceMicStarting=false;appState.voiceListening=false;syncVoiceUi();const code=String(e?.error||'');if(/not-allowed|service-not-allowed/.test(code)){readingMicPermissionDenied=true;toast('Permita o uso do microfone para responder por voz.');return;}if(!/aborted/.test(code))setTimeout(()=>{if(appState.readingAssistEnabled&&token===voiceListenToken)startVoiceListening(actions,contextKey,answerSurface);},300);};\n    rec.onend=()=>{clearVoiceStartTimers();if(appState.voiceRecognition===rec)appState.voiceRecognition=null;const wasListening=!!appState.voiceListening;voiceMicStarting=false;appState.voiceListening=false;syncVoiceUi();if(retryAfterEarlySpeech&&appState.readingAssistEnabled&&token===voiceListenToken){setTimeout(()=>startVoiceListening(actions,contextKey,answerSurface),180);return;}if(!handled&&wasListening&&appState.readingAssistEnabled&&token===voiceListenToken)setTimeout(()=>startVoiceListening(actions,contextKey,answerSurface),260);};\n"""

if old not in s:
    raise SystemExit('target recognition block not found')
s = s.replace(old, new, 1)
path.write_text(s, encoding='utf-8')
